import UIKit
struct Game {
    var id: Int
    var title: String
    var saved: Bool
}
final class GameCell: UITableViewCell {
    var representedID: Int?
    func configure(_ game: Game) {
        representedID = game.id
        textLabel?.text = game.title
        accessoryType = game.saved ? .checkmark : .none
        imageView?.image = nil
    }
    override func prepareForReuse() {
        representedID = nil
        super.prepareForReuse()
    }
}
@MainActor
final class CoverSource {
    private var pending: [Int: (UIImage) -> Void] = [:]
    func load(id: Int, done: @escaping (UIImage) -> Void) {
        pending[id] = done
    }
    func finish(id: Int, image: UIImage) {
        pending[id]?(image)
        pending[id] = nil
    }
}
@MainActor
func requestCover(cell: GameCell, id: Int, source: CoverSource) {
    source.load(id: id) { [weak cell] image in
        guard cell?.representedID == id else { return }
        cell?.imageView?.image = image
        cell?.setNeedsLayout()
    }
}
@MainActor
func checkRemembered() {
    let source = CoverSource()
    let cell = GameCell(style: .default, reuseIdentifier: "Game")
    cell.configure(Game(id: 61, title: "Маяки", saved: true))
    requestCover(cell: cell, id: 61, source: source)
    cell.prepareForReuse()
    cell.configure(Game(id: 63, title: "Лес", saved: false))
    source.finish(id: 61, image: UIImage())
    assert(cell.representedID == 63)
    assert(cell.textLabel?.text == "Лес")
    assert(cell.accessoryType == .none)
    assert(cell.imageView?.image == nil)
}

